PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, username TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, full_name TEXT NOT NULL, email TEXT, phone TEXT, role TEXT NOT NULL DEFAULT 'Employee', department TEXT, job_title TEXT, employment_type TEXT, start_date TEXT, salary REAL DEFAULT 0, status TEXT DEFAULT 'Active', created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS permissions (id TEXT PRIMARY KEY, key TEXT UNIQUE NOT NULL, label TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS role_permissions (role TEXT NOT NULL, permission_id TEXT NOT NULL, PRIMARY KEY(role,permission_id));
CREATE TABLE IF NOT EXISTS user_permissions (user_id TEXT NOT NULL, permission_id TEXT NOT NULL, allowed INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(user_id,permission_id));
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, token_hash TEXT UNIQUE NOT NULL, expires_at TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS clients (id TEXT PRIMARY KEY, company_name TEXT NOT NULL, contact_person TEXT, phone TEXT, email TEXT, website TEXT, instagram TEXT, industry TEXT, company_size TEXT, status TEXT DEFAULT 'New Lead', score INTEGER DEFAULT 0, notes TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS client_communications (id TEXT PRIMARY KEY, client_id TEXT NOT NULL, type TEXT NOT NULL, subject TEXT, content TEXT, communication_date TEXT DEFAULT CURRENT_TIMESTAMP, created_by TEXT);
CREATE TABLE IF NOT EXISTS projects (id TEXT PRIMARY KEY, title TEXT NOT NULL, client_id TEXT, manager_id TEXT, description TEXT, budget REAL DEFAULT 0, start_date TEXT, deadline TEXT, priority TEXT DEFAULT 'Medium', status TEXT DEFAULT 'Planning', progress INTEGER DEFAULT 0, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS project_members (project_id TEXT NOT NULL, user_id TEXT NOT NULL, member_role TEXT, PRIMARY KEY(project_id,user_id));
CREATE TABLE IF NOT EXISTS tasks (id TEXT PRIMARY KEY, title TEXT NOT NULL, project_id TEXT, assigned_to TEXT, priority TEXT DEFAULT 'Medium', status TEXT DEFAULT 'TODO', deadline TEXT, description TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS freelancers (id TEXT PRIMARY KEY, name TEXT NOT NULL, specialty TEXT, phone TEXT, email TEXT, city TEXT, portfolio TEXT, rate REAL DEFAULT 0, equipment TEXT, experience TEXT, availability TEXT DEFAULT 'Available', status TEXT DEFAULT 'Active', notes TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS freelancer_projects (freelancer_id TEXT NOT NULL, project_id TEXT NOT NULL, role TEXT, agreed_amount REAL DEFAULT 0, paid_amount REAL DEFAULT 0, quality_rating INTEGER DEFAULT 0, delivery_rating INTEGER DEFAULT 0, communication_rating INTEGER DEFAULT 0, client_satisfaction INTEGER DEFAULT 0, notes TEXT, PRIMARY KEY(freelancer_id,project_id));
CREATE TABLE IF NOT EXISTS attendance (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, date TEXT NOT NULL, check_in TEXT, check_out TEXT, type TEXT DEFAULT 'Present', notes TEXT);
CREATE TABLE IF NOT EXISTS leave_requests (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, leave_type TEXT NOT NULL, start_date TEXT NOT NULL, end_date TEXT NOT NULL, days REAL DEFAULT 1, reason TEXT, status TEXT DEFAULT 'Pending', approved_by TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS evaluations (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, month TEXT NOT NULL, quality INTEGER DEFAULT 0, speed INTEGER DEFAULT 0, responsibility INTEGER DEFAULT 0, teamwork INTEGER DEFAULT 0, notes TEXT, evaluated_by TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS contracts (id TEXT PRIMARY KEY, type TEXT NOT NULL, title TEXT NOT NULL, client_id TEXT, freelancer_id TEXT, employee_id TEXT, project_id TEXT, contract_number TEXT, start_date TEXT, end_date TEXT, amount REAL DEFAULT 0, status TEXT DEFAULT 'Draft', file_url TEXT, notes TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS finances (id TEXT PRIMARY KEY, type TEXT NOT NULL, category TEXT NOT NULL, amount REAL NOT NULL, project_id TEXT, client_id TEXT, freelancer_id TEXT, description TEXT, date TEXT NOT NULL, created_by TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS invoices (id TEXT PRIMARY KEY, invoice_number TEXT UNIQUE NOT NULL, client_id TEXT NOT NULL, project_id TEXT, amount REAL NOT NULL, paid_amount REAL DEFAULT 0, due_date TEXT, status TEXT DEFAULT 'Unpaid', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS requests (id TEXT PRIMARY KEY, ticket_number TEXT UNIQUE NOT NULL, user_id TEXT NOT NULL, type TEXT NOT NULL, title TEXT NOT NULL, description TEXT, priority TEXT DEFAULT 'Medium', status TEXT DEFAULT 'Pending', assigned_to TEXT, manager_reply TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS conversations (id TEXT PRIMARY KEY, type TEXT NOT NULL, title TEXT, project_id TEXT, created_by TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS conversation_members (conversation_id TEXT NOT NULL, user_id TEXT NOT NULL, PRIMARY KEY(conversation_id,user_id));
CREATE TABLE IF NOT EXISTS messages (id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL, sender_id TEXT NOT NULL, message TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS activity_logs (id TEXT PRIMARY KEY, user_id TEXT, action TEXT NOT NULL, entity_type TEXT, entity_id TEXT, description TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_tasks_deadline ON tasks(deadline); CREATE INDEX IF NOT EXISTS idx_projects_deadline ON projects(deadline); CREATE INDEX IF NOT EXISTS idx_finance_date ON finances(date);
